import React, { useEffect, useState } from 'react'
import { connect } from 'react-redux'

import { notification } from 'antd'
import authAction from '../../redux/auth/actions'

import CircularLoader from '../../components/CircularLoader'
import { useHistory } from 'react-router'

const { verifySSOToken } = authAction

const SSOMitra = (props) => {
  const [ssoToken, setSSOToken] = useState(null)
  const [redirectTo, setRedirectTo] = useState('/')

  const history = useHistory()

  const getQueryParams = () => {
    const queryString = window.location.search
    const appToken = new URLSearchParams(queryString).get('app_token')
    let redirectRoute = new URLSearchParams(queryString).get('redirectTo')

    if (!appToken) {
      notification['error']({ message: 'Invalid Request' })
      return
    }

    if (redirectRoute) {
      setRedirectTo(redirectRoute)
    }
    setSSOToken(appToken)
  }

  const verifyToken = () => {
    const payload = {
      access_token: ssoToken
    }
    props.verifySSOToken(payload)
  }

  useEffect(() => {
    getQueryParams()
  }, [])

  useEffect(() => {
    if (ssoToken) {
      verifyToken()
    }
  }, [ssoToken])

  useEffect(() => {
    if (props.ssoTokenVerified) {
      window.sessionStorage.setItem('isSSOSession', true)
      window.localStorage.setItem('lang', 'id')

      if (redirectTo && redirectTo.includes('policydetail')) {
        const policyRefId = redirectTo.split('policydetail/')[1]
        window.sessionStorage.setItem('ssoPolicyId', policyRefId)
      }

      history.push(redirectTo)
    }
  }, [props.ssoTokenVerified])

  useEffect(() => {
    if (!props.ssoTokenVerified && props.tokenFailureMessage !== '') {
      notification['error']({ message: props.tokenFailureMessage })
    }
  }, [props.ssoTokenVerified, props.tokenFailureMessage])

  return <CircularLoader />
}

export default connect(
  state => ({
    ssoTokenVerified: state.Auth.ssoTokenVerified,
    tokenFailureMessage: state.Auth.tokenFailureMessage
  }),
  {
    verifySSOToken
  }
)(SSOMitra)
